<?php
require_once 'functions.php';require_role(['admin']);
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM tbl_produk WHERE id_produk=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){$id=(int)$_POST['id'];try{$pdo->prepare("DELETE FROM tbl_produk WHERE id_produk=?")->execute([$id]);flash('Produk dihapus.');}catch(Throwable $e){flash('Produk tidak bisa dihapus karena sudah digunakan dalam transaksi. Nonaktifkan produk saja.','error');}go('produk.php');}
 $id=(int)($_POST['id_produk']??0);$kode=trim($_POST['kode_produk']);$nama=trim($_POST['nama_produk']);$cat=(int)$_POST['id_kategori'];$harga=(float)$_POST['harga'];$stok=(int)$_POST['stok'];$jenis=$_POST['jenis_produk'];$status=$_POST['status'];$desc=trim($_POST['deskripsi']);$satuan=trim($_POST['satuan']);$foto=$_POST['foto_lama']??null;
 if(!empty($_FILES['foto']['name'])){$ext=strtolower(pathinfo($_FILES['foto']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp','gif'])){flash('Format foto harus JPG, PNG, WEBP, atau GIF.','error');go('produk.php');}if($_FILES['foto']['size']>3*1024*1024){flash('Ukuran foto maksimal 3 MB.','error');go('produk.php');}$dir=__DIR__.'/uploads/produk';if(!is_dir($dir))mkdir($dir,0775,true);$file='prd_'.bin2hex(random_bytes(8)).'.'.$ext;if(move_uploaded_file($_FILES['foto']['tmp_name'],$dir.'/'.$file))$foto='uploads/produk/'.$file;}
 try{if($id){$pdo->prepare("UPDATE tbl_produk SET id_kategori=?,kode_produk=?,nama_produk=?,deskripsi=?,harga=?,stok=?,satuan=?,foto=?,jenis_produk=?,status=? WHERE id_produk=?")->execute([$cat,$kode,$nama,$desc,$harga,$stok,$satuan,$foto,$jenis,$status,$id]);log_activity($pdo,'Edit produk',$nama);flash('Produk berhasil diperbarui.');}else{$pdo->prepare("INSERT INTO tbl_produk(id_kategori,kode_produk,nama_produk,deskripsi,harga,stok,satuan,foto,jenis_produk,status) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$cat,$kode,$nama,$desc,$harga,$stok,$satuan,$foto,$jenis,$status]);log_activity($pdo,'Tambah produk',$nama);flash('Produk berhasil ditambahkan.');}}catch(Throwable $e){flash('Gagal menyimpan. Pastikan kode produk belum dipakai. '.$e->getMessage(),'error');}go('produk.php');
}
$cats=$pdo->query("SELECT * FROM tbl_kategori ORDER BY COALESCE(id_parent,id_kategori),id_parent IS NOT NULL,nama_kategori")->fetchAll();$rows=$pdo->query("SELECT p.*,k.nama_kategori FROM tbl_produk p JOIN tbl_kategori k ON k.id_kategori=p.id_kategori ORDER BY p.id_produk DESC")->fetchAll();
layout_header('Kelola Produk');
?>
<div class="page-title"><div><span class="eyebrow">KATALOG TOKO</span><h1>Kelola Produk</h1><p>Tambah, ubah, nonaktifkan, dan unggah foto produk.</p></div></div>
<div class="panel"><h3><?=$edit?'Edit Produk':'Tambah Produk Baru'?></h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id_produk" value="<?=e($edit['id_produk']??'')?>"><input type="hidden" name="foto_lama" value="<?=e($edit['foto']??'')?>"><div class="form-grid"><div><label>Kode produk</label><input name="kode_produk" required value="<?=e($edit['kode_produk']??'')?>"></div><div><label>Nama produk</label><input name="nama_produk" required value="<?=e($edit['nama_produk']??'')?>"></div><div><label>Kategori</label><select name="id_kategori" required><?php foreach($cats as $c):?><option value="<?=$c['id_kategori']?>" <?=($edit['id_kategori']??'')==$c['id_kategori']?'selected':''?>><?=e($c['id_parent']?'— '.$c['nama_kategori']:$c['nama_kategori'])?></option><?php endforeach;?></select></div><div><label>Jenis produk</label><select name="jenis_produk"><?php foreach(['barang','jasa','topup'] as $v):?><option <?=$v===($edit['jenis_produk']??'barang')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div><label>Harga</label><input type="number" min="0" step="100" name="harga" required value="<?=e($edit['harga']??'0')?>"></div><div><label>Stok</label><input type="number" min="0" name="stok" value="<?=e($edit['stok']??'0')?>"></div><div><label>Satuan</label><input name="satuan" value="<?=e($edit['satuan']??'pcs')?>"></div><div><label>Status</label><select name="status"><option value="aktif">Aktif</option><option value="nonaktif" <?=($edit['status']??'')==='nonaktif'?'selected':''?>>Nonaktif</option></select></div></div><label>Deskripsi</label><textarea name="deskripsi" rows="3"><?=e($edit['deskripsi']??'')?></textarea><label>Foto produk (maks. 3 MB)</label><input type="file" name="foto" accept="image/*" data-preview="#foto-preview"><img id="foto-preview" class="preview-img" src="<?=e(product_image($edit['foto']??null))?>" alt="Preview foto"><div class="form-actions"><button class="btn btn-primary">Simpan Produk</button><?php if($edit):?><a class="btn btn-outline" href="produk.php">Batal Edit</a><?php endif;?></div></form></div>
<div class="section-head"><h2>Daftar Produk</h2><input style="max-width:260px" placeholder="Cari produk..." data-search-table="#produk-table"></div><div class="table-wrap"><table id="produk-table"><thead><tr><th>Foto</th><th>Kode</th><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img class="table-thumb" src="<?=e(product_image($r['foto']))?>"></td><td><?=e($r['kode_produk'])?></td><td><?=e($r['nama_produk'])?></td><td><?=e($r['nama_kategori'])?></td><td><?=rupiah($r['harga'])?></td><td><?=$r['stok']?></td><td><?=e($r['status'])?></td><td><a class="btn btn-outline btn-sm" href="?edit=<?=$r['id_produk']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id_produk']?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus produk ini?">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_footer(); ?>
